function wxHoldButton(r){const old=$('#wxHoldSpeak');if(old){old.remove();return}const b=document.createElement('button');b.type='button';b.id='wxHoldSpeak';b.className='wx18-hold';b.textContent='按住说话 · 上滑取消';$('#composer').before(b);let startY=0,cancelled=false,ended=false;b.onpointerdown=async e=>{e.preventDefault();if(wxRecording||busy||voiceProcessing)return;startY=e.clientY;cancelled=false;ended=false;b.setPointerCapture(e.pointerId);try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(ended){stream.getTracks().forEach(t=>t.stop());return}const rec=new MediaRecorder(stream),chunks=[],at=Date.now();rec.wxCancel=()=>cancelled=true;wxRecording=rec;rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};const timer=setTimeout(()=>rec.stop(),60000);rec.onstop=async()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());wxRecording=null;b.textContent='按住说话 · 上滑取消';if(cancelled||Date.now()-at<500)return;try{const blob=new Blob(chunks,{type:rec.mimeType}),data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)}),key='voice:'+crypto.randomUUID();await mediaWrite(key,data);const extra={media:{type:'voice',key}};if(voiceReady()&&voiceSettings.stt){try{extra.transcript=await wxSpeechText(blob)}catch(e){toast('录音已保留，转写未完成：'+e.message)}}await sendMessage(r,'[语音 '+Math.ceil((Date.now()-at)/1000)+' 秒]',null,{extra})}catch(e){toast(e.message)}};rec.start();b.textContent='正在录音… 松开发送，上滑取消'}catch(err){toast(err.name==='NotAllowedError'?'请允许浏览器使用麦克风':'录音不可用：'+err.message)}};b.onpointermove=e=>{cancelled=startY-e.clientY>60;if(wxRecording)b.textContent=cancelled?'松开取消':'正在录音… 松开发送'};const finish=()=>{ended=true;if(wxRecording?.state==='recording')wxRecording.stop()};b.onpointerup=finish;b.onpointercancel=()=>{cancelled=true;finish()};}
async function wxTranscribe(r,m){if(m.transcript){wxPanel('<h2>语音文字</h2><p>'+escapeHtml(m.transcript)+'</p>');return}if(!voiceReady()||!voiceSettings.stt){toast('请先配置语音 API 和转写模型');return}try{const src=mediaCache.get(m.media.key);if(!src)throw Error('录音文件不存在');const blob=await(await fetch(src)).blob(),form=new FormData();form.append('file',blob,blob.type.includes('mp4')?'voice.m4a':blob.type.includes('ogg')?'voice.ogg':'voice.webm');form.append('model',voiceSettings.stt);const c=effectiveVoiceConfig(),res=await fetch(PalaisCore.apiURL(c.base,'audio/transcriptions'),{method:'POST',headers:{Authorization:'Bearer '+c.key},body:form,signal:AbortSignal.timeout(60000)}),data=await res.json();if(!res.ok||!data.text)throw Error(data.error?.message||'转写失败');wxHistoryCommit(r.id,histories[r.id].map(x=>x.id===m.id?{...x,transcript:data.text}:x));wxPanel('<h2>语音文字</h2><p>'+escapeHtml(data.text)+'</p>')}catch(e){toast(friendly(e))}}
