function wxAppHead(name,extra=''){return `${title(name,'LITTLE EVERYDAY',extra)}<button class="text-button" id="wxAppBack">‹ 返回桌面</button>`}
function wxDiary(date=PalaisCore.dateKey()){screen.innerHTML=`<section class="view wx18-diary">${wxAppHead('日记','<button class="round" id="newDiary">＋</button>')}<p class="section-note">${escapeHtml(date)} · 横线信纸，留下今天的小心情</p>${wx18.diaries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<button class="wx18-entry" data-diary="${escapeHtml(e.id)}"><small>${e.date} · ${escapeHtml(e.weather)} · ${escapeHtml(e.mood)}</small><b>${escapeHtml(e.title)}</b><p>${escapeHtml(e.text.slice(0,100))}</p></button>`).join('')||'<p class="soft-empty">还没有日记，写下第一篇吧。</p>'}</section>`;$('#wxAppBack').onclick=()=>go('home');$('#newDiary').onclick=()=>wxEntryEditor('diaries',null,date);screen.querySelectorAll('[data-diary]').forEach(b=>b.onclick=()=>wxEntryEditor('diaries',b.dataset.diary))}
function wxNotes(){screen.innerHTML=`<section class="view">${wxAppHead('备忘录','<button class="round" id="newMemo">＋</button>')}${wx18.notes.slice().sort((a,b)=>b.updatedAt-a.updatedAt).map(e=>`<button class="wx18-entry" data-note="${escapeHtml(e.id)}"><b>${escapeHtml(e.title)}</b><p>${escapeHtml(e.text.slice(0,120))}</p><small>${e.date}</small></button>`).join('')||'<p class="soft-empty">记下一件不想忘记的事。</p>'}</section>`;$('#wxAppBack').onclick=()=>go('home');$('#newMemo').onclick=()=>wxEntryEditor('notes');screen.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>wxEntryEditor('notes',b.dataset.note))}
function wxEntryEditor(kind,id,date=PalaisCore.dateKey()){const old=wx18[kind].find(x=>x.id===id),diary=kind==='diaries',d=wxPanel(`<form id="wxEntryForm"><h2>${old?'编辑': '新建'}${diary?'日记':'备忘录'}</h2><label>日期<input type="date" name="date" required value="${old?.date||date}"></label><label>标题<input name="title" maxlength="80" required value="${escapeHtml(old?.title||'')}"></label>${diary?`<div class="wx18-stamps"><label>天气<select name="weather">${['晴','多云','阴','雨','雪'].map(v=>`<option ${v===old?.weather?'selected':''}>${v}</option>`).join('')}</select></label><label>心情<select name="mood">${['平静','开心','心动','疲惫','难过'].map(v=>`<option ${v===old?.mood?'selected':''}>${v}</option>`).join('')}</select></label></div>`:''}<label>正文<textarea class="${diary?'wx18-paper':''}" name="text" rows="9" maxlength="20000">${escapeHtml(old?.text||'')}</textarea></label><div class="actions"><button type="button" id="wxEntryCancel" class="secondary">取消</button><button class="primary">保存</button></div>${old?'<button type="button" class="text-button danger" id="wxEntryDelete">删除这篇记录</button>':''}</form>`);$('#wxEntryCancel').onclick=()=>d.close();$('#wxEntryForm').onsubmit=e=>{e.preventDefault();try{const f=e.target,entry=PalaisWX18.entry({date:f.date.value,title:f.title.value,text:f.text.value,weather:f.weather?.value,mood:f.mood?.value},id||crypto.randomUUID(),Date.now());wxPut({...wx18,[kind]:old?wx18[kind].map(x=>x.id===id?entry:x):[...wx18[kind],entry]});d.close();if(tab==='calendar')renderCalendar();else if(diary)wxDiary(entry.date);else wxNotes();toast('已保存')}catch(e){toast(e.message)}};if(old)$('#wxEntryDelete').onclick=()=>{const b=$('#wxEntryDelete');if(!b.dataset.confirm){b.dataset.confirm='yes';b.textContent='再次点击确认删除';return}try{wxPut({...wx18,[kind]:wx18[kind].filter(x=>x.id!==id)});d.close();if(tab==='calendar')renderCalendar();else if(diary)wxDiary();else wxNotes()}catch(e){toast(e.message)}}}
function wxAlbum(){const keys=new Set;Object.values(histories).forEach(list=>list.forEach(m=>{if(m.media?.type==='image')keys.add(m.media.key)}));moments.forEach(m=>{if(mediaCache.has('moment:'+m.id))keys.add('moment:'+m.id)});const rows=[...keys].filter(k=>mediaCache.has(k));screen.innerHTML=`<section class="view">${wxAppHead('相册')}<p class="section-note">聊天与朋友圈照片 · ${rows.length} 张</p><div class="wx18-album">${rows.map((k,i)=>`<button data-photo="${i}"><img src="${mediaCache.get(k)}" alt="照片 ${i+1}"></button>`).join('')}</div>${rows.length?'':'<p class="soft-empty">发过的照片会在这里汇总。</p>'}</section>`;$('#wxAppBack').onclick=()=>go('home');screen.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>wxPhoto(mediaCache.get(rows[Number(b.dataset.photo)])))}
function wxSettings(){screen.innerHTML=`<section class="view">${wxAppHead('设置')}<button class="menu-button" id="wxEditSelf">修改资料与头像 ›</button><button class="menu-button" id="wxWallpaper">聊天壁纸 ›</button><button class="menu-button" id="wxPhoneWallpaper">桌面主题与壁纸 ›</button><button class="menu-button" id="wxRestoreDemo">恢复示例数据 ›</button><p class="section-note">记录和图片只保存在此浏览器；API 请求发送到你填写的服务商。音视频权限由浏览器单独管理。</p></section>`;$('#wxAppBack').onclick=()=>go('home');$('#wxEditSelf').onclick=renderProfile;$('#wxWallpaper').onclick=editDefaultBackground;$('#wxPhoneWallpaper').onclick=()=>wxDesktopWallpaper();$('#wxRestoreDemo').onclick=()=>{const d=wxPanel('<h2>恢复示例联系人</h2><p>重新加入玫瑰小姐和月光先生；已有联系人、聊天和余额会保留。</p><button class="primary full" id="wxConfirmDemo">确认恢复</button>');$('#wxConfirmDemo').onclick=()=>{const old=roles;try{const examples=[{id:'rose',name:'玫瑰小姐',emoji:'🌷',prompt:'你是温柔细腻的朋友玫瑰小姐，自然地用中文聊天。'},{id:'lune',name:'月光先生',emoji:'🌙',prompt:'你是沉稳体贴的朋友月光先生，自然地用中文聊天。'}];roles=[...roles,...examples.filter(x=>!roles.some(r=>r.id===x.id))];persist();d.close();toast('示例联系人已恢复')}catch(e){roles=old;toast(e.message)}}}}
const wxOriginalCalendar=renderCalendar;renderCalendar=function(){wxOriginalCalendar();screen.querySelectorAll('[data-date]').forEach(b=>{const date=b.dataset.date,holiday=PalaisWX18.holiday(date);if(holiday){const s=document.createElement('small');s.className='wx18-holiday';s.textContent=holiday;b.append(s)}const ev=events.filter(e=>e.date===date);b.querySelector('i')?.remove();if(ev.length){const dots=document.createElement('span');dots.className='wx18-day-dots';dots.innerHTML=ev.slice(0,3).map((e,i)=>`<i style="background:${['#dc9db7','#9fbdaf','#afa8d6'][i]}"></i>`).join('');b.append(dots)}});const b=document.createElement('button');b.className='secondary full';b.textContent='查看 / 写 '+calendarSelected+' 的日记';b.onclick=()=>{const row=wx18.diaries.find(x=>x.date===calendarSelected);wxEntryEditor('diaries',row?.id,calendarSelected)};screen.querySelector('.view').append(b)};
desktopApps.diary=['▤','日记'];desktopApps.memos=['▥','备忘录'];desktopApps.album=['▧','相册'];desktopApps.settings=['⚙','设置'];PalaisDesktop.pages[1].apps.push('diary','memos','album');PalaisDesktop.pages[2].apps.push('settings');
const wxOriginalDownload=download;download=function(name,data){if(data?.roles&&data?.histories)data={...data,wx18};return wxOriginalDownload(name,data)};
window.addEventListener('pagehide',()=>{if(wxRecording){wxRecording.wxCancel?.();if(wxRecording.state==='recording')wxRecording.stop()}if(wxCall){wxCall.camera?.getTracks().forEach(t=>t.stop());stopVoice();$('#utilityDialog').close()}});
function wxDesktopWallpaper(){const d=wxPanel('<h2>桌面壁纸</h2><input hidden id="wxDesktopFile" type="file" accept="image/png,image/jpeg,image/webp"><button class="primary full" id="wxUploadDesktop">上传壁纸</button><button class="secondary full" id="wxClearDesktop">恢复默认壁纸</button><button class="text-button" id="wxDesktopColors">修改主题配色</button>');$('#wxUploadDesktop').onclick=()=>$('#wxDesktopFile').click();$('#wxDesktopFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;await mediaWrite('wallpaper:desktop',await prepareImage(f,1600));d.close();go('home');toast('桌面壁纸已更新')}catch(e){toast(e.message)}};$('#wxClearDesktop').onclick=async()=>{try{await mediaWrite('wallpaper:desktop',null);d.close();go('home')}catch(e){toast(e.message)}};$('#wxDesktopColors').onclick=()=>{d.close();openThemePicker(()=>render())}}
render();

async function wxSpeechText(blob){const f=new FormData();f.append('file',blob,blob.type.includes('mp4')?'voice.m4a':blob.type.includes('ogg')?'voice.ogg':'voice.webm');f.append('model',voiceSettings.stt);const c=effectiveVoiceConfig(),res=await fetch(PalaisCore.apiURL(c.base,'audio/transcriptions'),{method:'POST',headers:{Authorization:'Bearer '+c.key},body:f,signal:AbortSignal.timeout(60000)}),data=await res.json();if(!res.ok||!data.text)throw Error(data.error?.message||'转写未完成');return data.text}
